pub fn supplies_purpose() -> &'static str {
    "Supply manifests for fuel, medical, signage, sanitation, food, and repair shipments moving between ranger stations, camp stores, and trail crews."
}

pub fn supplies_summary() -> String {
    let campsites = supply_manifests();
    let shard_total: u32 = campsites.iter().map(|item| item.shard).sum();
    let record_total: u32 = campsites.iter().map(|item| item.survey).sum();
    let pressure_total: u32 = campsites.iter().map(|item| item.pressure).sum();
    format!("supplies count={} shard={} rec={} pressure={}", campsites.len(), shard_total, record_total, pressure_total)
}

pub fn supplies_family_window(family: &str, limit: usize) -> Vec<SupplyManifest> {
    supply_manifests().into_iter().filter(|item| item.family == family).take(limit).collect()
}

pub fn supplies_weighted_total(seed: u32) -> u64 {
    supply_manifests().into_iter().enumerate().map(|(index, item)| {
        let bias = (seed as u64 + index as u64 % 31) + 1;
        bias * (item.shard as u64 + item.survey as u64 * 3 + item.pressure as u64 * 5)
    }).sum()
}

pub fn supplies_nearest(shard: u32, survey: u32) -> Option<SupplyManifest> {
    supply_manifests().into_iter().min_by_key(|item| {
        let a = item.shard.abs_diff(shard) as u64;
        let b = item.survey.abs_diff(survey) as u64;
        a * 7 + b * 3 + item.pressure as u64
    })
}

pub fn supplies_note_digest(limit: usize) -> Vec<String> {
    supply_manifests().into_iter().take(limit).map(|item| format!("{}:{}:{}", item.key, item.family, item.note)).collect()
}
